import { createHmac } from 'node:crypto'

export interface ConnectorConfig {
  airtableBaseId: string
  airtableTableIdOrName: string
  airtablePersonalAccessToken: string
  shopifyWebhookSecret: string
  fetch?: typeof fetch
}

export interface ShopifyOrderPaidPayload {
  id: number
  email: string
  total_price: string
}

export interface AirtableCreateRecordResponse {
  records: Array<{
    id: string
    fields: {
      'Order ID': string
      'Customer Email': string
      Total: number
    }
    createdTime: string
  }>
}

export interface HandleResult {
  airtableRecordId: string
  createdTime: string
}

function validatePayload(payload: unknown): asserts payload is ShopifyOrderPaidPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (typeof p.id !== 'number') {
    throw new Error('Missing required field: id (order ID)')
  }
  if (typeof p.email !== 'string' || !p.email) {
    throw new Error('Missing required field: email (customer email)')
  }
  if (typeof p.total_price !== 'string' || !p.total_price) {
    throw new Error('Missing required field: total_price')
  }
}

function verifyHmacSignature(payload: string, signature: string, secret: string): boolean {
  const expected = createHmac('sha256', secret).update(payload).digest('base64')
  return signature === expected
}

export async function handle(
  payload: ShopifyOrderPaidPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  validatePayload(payload)

  const url = `https://api.airtable.com/v0/${config.airtableBaseId}/${config.airtableTableIdOrName}`

  const total = Number(payload.total_price)
  if (Number.isNaN(total)) {
    throw new Error(`Invalid total_price: "${payload.total_price}" is not a valid number`)
  }

  const body = {
    records: [
      {
        fields: {
          'Order ID': String(payload.id),
          'Customer Email': payload.email,
          Total: total,
        },
      },
    ],
  }

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.airtablePersonalAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`Airtable API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const data = (await response.json()) as AirtableCreateRecordResponse

  if (!data.records || data.records.length === 0) {
    throw new Error('Airtable returned no records in response')
  }

  const created = data.records[0]
  return {
    airtableRecordId: created.id,
    createdTime: created.createdTime,
  }
}

export async function handleWebhook(
  request: Request,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  const signature = request.headers.get('x-shopify-hmac-sha256')
  if (!signature) {
    throw new Error('Missing X-Shopify-Hmac-Sha256 header')
  }

  const rawBody = await request.text()
  if (!verifyHmacSignature(rawBody, signature, config.shopifyWebhookSecret)) {
    throw new Error('Invalid HMAC signature')
  }

  let payload: ShopifyOrderPaidPayload
  try {
    payload = JSON.parse(rawBody) as ShopifyOrderPaidPayload
  } catch {
    throw new Error('Invalid JSON payload')
  }

  return handle(payload, { ...config, fetch: fetchImpl })
}

