    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.airtable.com/v0/appTestBase/tblTestTable' &&
      req.method === 'POST'
        ? jsonResponse(TARGET_ENDPOINTS[0].response, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: ShopifyOrderPaidPayload = {
      id: 9876543210,
      email: 'test@example.com',
      total_price: '299.50',
    }

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(calls).toHaveLength(1)
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://api.airtable.com/v0/appTestBase/tblTestTable')
    expect(calls[0].headers.get('authorization')).toBe('Bearer pat_test_token')
    expect(calls[0].json).toEqual({
      records: [
        {
          fields: {
            'Order ID': '9876543210',
            'Customer Email': 'test@example.com',
            Total: 299.5,
          },
        },
      ],
    })
    expect(result.airtableRecordId).toBe('rec123abc')
  })

  it('throws on missing id field', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { email: 'test@example.com', total_price: '100' } as unknown as ShopifyOrderPaidPayload
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: id')
