  it('throws when HMAC header is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const request = new Request('https://example.com/webhook', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: validPayload,
    })
    await expect(handleWebhook(request, { ...baseConfig, fetch })).rejects.toThrow('Missing X-Shopify-Hmac-Sha256 header')
  })

  it('throws when HMAC signature is invalid', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const request = new Request('https://example.com/webhook', {
      method: 'POST',
      headers: {
        'x-shopify-hmac-sha256': 'invalid_signature',
        'content-type': 'application/json',
      },
      body: validPayload,
    })
    await expect(handleWebhook(request, { ...baseConfig, fetch })).rejects.toThrow('Invalid HMAC signature')
  })

  it('throws on invalid JSON payload', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const crypto = await import('node:crypto')
    const expectedSignature = crypto.createHmac('sha256', baseConfig.shopifyWebhookSecret)
      .update('not json')
      .digest('base64')

    const request = new Request('https://example.com/webhook', {
      method: 'POST',
      headers: {
        'x-shopify-hmac-sha256': expectedSignature,
        'content-type': 'application/json',
      },
      body: 'not json',
    })
    await expect(handleWebhook(request, { ...baseConfig, fetch })).rejects.toThrow('Invalid JSON payload')
  })

  it('propagates validation errors from handle', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const invalidPayload = JSON.stringify({ id: 123, total_price: '100' })
